'use strict';
window.createPhoenixQuestPages=function({state,tasks,hubs,engine,progressUI,navigate}){
 const progressSlots=new Map(),contexts=new Map();
 const hubUI=window.createPhoenixQuestHubs({state,tasks,hubs,engine,navigate});
 const make=(tag,text,cls)=>{const el=document.createElement(tag);if(text)el.textContent=text;if(cls)el.className=cls;return el;};
 const optionalPanels=[],optionalOpen=new Map(),model=window.PhoenixNearbyModel,modelContext={tasks,engine,state};let activeOptionalReturn=null;
 const optionalLink=(name,href)=>{const a=make('a',name);a.href=href;a.dataset.optionalStop='true';return a;};
 function riskId(id){if(id==='poi-4')return id;return window.PHOENIX_PROGRESS_DATA.riskQuests.includes(id)?id:null;}
 function riskVisible(id){const info=model.state(id,modelContext);if(info.complete||info.missed)return false;if(id==='poi-4'&&engine.facts(state.progress).griffin)return false;const wolf=window.__phoenixMedallion,active=wolf?.getActiveWarning?.();if(active&&(id==='poi-4'?active.id==='crystal-skull-cutoff':active.id?.startsWith('departure-risk:')&&active.id.includes(id)))return true;return !(wolf?.getHistory?.()||[]).some(w=>id==='poi-4'?w.id==='crystal-skull-cutoff':w.id?.startsWith('departure-risk:')&&w.id.includes(id));}
 function buildOptional(q,t){for(const stage of t.stages){const detours=[...new Map((stage.detours||[]).filter(d=>tasks[d.task]).map(d=>[d.task,d])).values()];if(!detours.length)continue;const node=document.querySelector('#'+t.view+' [data-stage="'+stage.id+'"] .quest-context-links[aria-label="Optional nearby stops"]');if(!node)continue;const details=make('details',null,'optional-stops'),summary=make('summary'),list=make('ul'),rows=[];details.append(summary,list);for(const detour of detours){const id=detour.task,task=tasks[id],row=make('li'),service=window.PHOENIX_MAP.markers.find(m=>m.task===id&&m.type==='service'),href=service?'#economy-merchants/'+service.id:'#'+task.view+(detour.stage?'/'+detour.stage:'');const a=optionalLink(task.name,href),status=make('span',null,'optional-stop-status'),required=make('div',null,'optional-stop-prerequisite'),warning=make('p',null,'optional-stop-warning');row.append(a,status,required,warning);list.append(row);rows.push({id,row,status,required,warning});}const mainRisk=node.closest('.stage-content').querySelector(':scope>.risk-note'),stageRisk=window.PhoenixWarningCatalog.context(q,stage.id);if(mainRisk&&detours.some(d=>d.task===stageRisk))mainRisk.hidden=true;node.replaceWith(details);const panel={q,details,summary,rows};optionalPanels.push(panel);details.addEventListener('toggle',()=>{const all=model.counts(rows.map(r=>r.id),modelContext).allCompleted;if(all){if(details.open)details.open=false;return;}if(optionalOpen.get(q)===details.open)return;optionalOpen.set(q,details.open);for(const other of optionalPanels.filter(p=>p.q===q&&p!==panel))if(!model.counts(other.rows.map(r=>r.id),modelContext).allCompleted)other.details.open=details.open;});}}
 function refreshOptional(){for(const p of optionalPanels){const counts=model.counts(p.rows.map(r=>r.id),modelContext);let hasRisk=false;for(const row of p.rows){const info=model.state(row.id,modelContext);row.status.textContent=info.complete?'Completed':info.missed?'Recorded failed':info.blocked?'Prerequisite needed':info.unknown?'Availability unconfirmed':'';row.required.replaceChildren();const prerequisite=model.prerequisite(row.id,tasks);if(info.blocked&&prerequisite)row.required.append(optionalLink(prerequisite.text,prerequisite.href));row.required.hidden=!row.required.childNodes.length;const risk=riskId(row.id),show=risk&&riskVisible(row.id);row.warning.hidden=!show;if(show){hasRisk=true;const explanation=window.PhoenixWarningCatalog.get(risk,tasks);row.warning.replaceChildren(make('span',explanation.short));const b=make('button','Full warning details','warning-details-trigger');b.type='button';b.dataset.warningDetails=risk;row.warning.append(b);}else row.warning.replaceChildren();}p.summary.textContent='Optional stops · '+(counts.allCompleted?'All completed':counts.unfinished+' unfinished / '+counts.total+' total')+(hasRisk?' · ⚠ Missable risk':'');p.details.open=counts.allCompleted?false:optionalOpen.get(p.q)===true;}}
 document.addEventListener('click',event=>{const link=event.target.closest('a[data-optional-stop]');if(link&&!event.metaKey&&!event.ctrlKey&&!event.shiftKey&&!event.altKey&&event.button===0){event.preventDefault();event.stopPropagation();const origin={hash:location.hash||'#home',y:(window.PhoenixViewport||window).scrollY},href=link.getAttribute('href');if(href===origin.hash)return;navigate(href);history.replaceState({...history.state,optionalStopOrigin:origin},'',location.href);refreshOptionalReturn();return;}const marker=history.state?.optionalStopOrigin,back=event.target.closest('[data-exploration-return],[data-diagram-return],[data-return-hub],[data-optional-return]');if(marker&&back&&event.button===0){event.preventDefault();event.stopImmediatePropagation();history.back();}},true);
 function refreshOptionalReturn(){const marker=history.state?.optionalStopOrigin,root=document.getElementById(location.hash.slice(1).split('/')[0]),returning=activeOptionalReturn&&activeOptionalReturn.hash===(location.hash||'#home')?activeOptionalReturn:null;for(const b of document.querySelectorAll('[data-optional-return-label]')){b.textContent=b.dataset.optionalReturnLabel;delete b.dataset.optionalReturnLabel;}for(const b of document.querySelectorAll('[data-optional-return]'))b.remove();if(marker&&root){let b=root.querySelector('[data-exploration-return],[data-diagram-return],[data-return-hub]');if(b){b.dataset.optionalReturnLabel=b.textContent;b.textContent='Return to walkthrough';}else{b=make('button','Return to walkthrough','optional-source-return');b.type='button';b.dataset.optionalReturn='true';(root.querySelector('.reading-panel,.location-card,.main-parchment')||root).prepend(b);}}activeOptionalReturn=marker||null;if(returning)requestAnimationFrame(()=>requestAnimationFrame(()=>requestAnimationFrame(()=>(window.PhoenixViewport||window).scrollTo(0,returning.y))));}
 document.addEventListener('click',event=>{if(event.target.closest('.medallion-warning'))requestAnimationFrame(refreshOptional);});

 window.PhoenixQuestPages={destination(id){const t=tasks[id];return '#'+t.view+'/'+(t.stages.some(s=>s.id===state.stageByView[t.view])?state.stageByView[t.view]:t.stages[0].id);}};
 for(const [id,t]of Object.entries(tasks)){if(!t.stages)continue;const section=document.getElementById(t.view),panel=section.querySelector('.reading-panel'),heading=section.querySelector('.page-heading');
  section.querySelector('.crumbs')?.remove();const step=panel.querySelector('.stage-panel'),nav=panel.querySelector('.quest-step-nav');step.after(nav);const tools=panel.querySelector('.quest-page-tools');panel.after(tools);const wrapped=panel.querySelector(':scope>.exploration-quest-steps');if(wrapped)wrapped.replaceWith(...[...wrapped.children].filter(e=>e.tagName!=='SUMMARY'));
  const prep=panel.querySelector('.route-context');prep.classList.add('quest-preparation');prep.querySelector('summary').textContent='Preparation & quest details';prep.querySelector('summary').after(heading.querySelector('.lead'));panel.append(prep);const acquisition=panel.querySelector(':scope>.exploration-guidance');if(acquisition){const fold=make('details',null,'quest-acquisition');fold.append(make('summary','Acquisition details & references'),acquisition);panel.append(fold);}for(const note of panel.querySelectorAll(':scope>.quiet,:scope>.completion-meaning'))prep.append(note);
  buildOptional(id,t);
  const facts=make('p','White Orchard'+(Number.isFinite(t.level)?' · Suggested level '+t.level:''),'quest-page-facts');heading.append(facts);
  const hub=hubs.find(h=>h.items.find(k=>tasks[k].home===h.id&&window.PHOENIX_PROGRESS_DATA.quests[k])===id);
  if(hub){const slot=document.querySelector('[data-progress-hub="'+hub.id+'"]');progressSlots.set(id,{hub,slot,section,prep});hubUI.models.get(hub.id).progress.append(slot);slot.querySelector('.quest-progress').open=false;const previous=slot.querySelector('[data-card-prev]'),next=slot.querySelector('[data-card-next]');previous.textContent='←';next.textContent='→';previous.setAttribute('aria-label','Previous objective card');next.setAttribute('aria-label','Next objective card');previous.after(make('span','Swipe objectives'));slot.querySelector('.quiet').textContent='Record completed in-game objectives. These marks stay separate from your reading position.';

  }
  section.querySelectorAll('.walk-stage>button').forEach(b=>{if(b.textContent==='Update quest progress')b.remove();});
  const sources=panel.querySelector('.sources');if(sources){sources.querySelector('summary').textContent='Sources & verification';panel.append(sources);}
 }
 let last='';function refresh(event){refreshOptional();refreshOptionalReturn();const hubModel=hubUI.refresh(!event||event.type==='phoenix:route-rendered'),root=event?.detail?.root||location.hash.slice(1).split('/')[0];document.body.classList.toggle('reading-quest',!!document.querySelector('.quest-page:not([hidden])'));const t=Object.entries(tasks).find(([id,t])=>t.stages&&t.view===root);const current=t?{id:t[0],mode:'walkthrough'}:hubModel?{id:hubModel.q,mode:'hub'}:null;
  if(current){const item=progressSlots.get(current.id),deck=item.slot.querySelector('.quest-progress'),key=current.mode+':'+current.id;if(last!==key){if(last){const [mode,id]=last.split(':');const previous=progressSlots.get(id);if(previous)contexts.set(last,previous.slot.querySelector('.quest-progress').open);}const target=current.mode==='walkthrough'?item.section.querySelector('.quest-record-host'):hubUI.models.get(item.hub.id).progress;const prepTarget=current.mode==='walkthrough'?item.section.querySelector('.quest-record-host'):hubUI.models.get(item.hub.id).preparation;prepTarget.append(item.prep);target.append(item.slot);deck.open=contexts.has(key)?contexts.get(key):current.mode==='walkthrough';last=key;if(current.mode==='walkthrough')requestAnimationFrame(()=>progressUI.positionQuest(current.id));}}
 }
 for(const name of ['phoenix:route-rendered','phoenix:progress-committed','phoenix:progress-undone'])addEventListener(name,refresh);refresh();
 for(const item of progressSlots.values()){const back=item.section.querySelector('[data-return-hub]');back.onclick=event=>{if(history.state?.explorationReturn&&item.section.querySelector('[data-exploration-return]')){event.preventDefault();event.stopPropagation();item.section.querySelector('[data-exploration-return]').click();}};}
 return window.PhoenixQuestPages;
};
